1	/**
2	 * turn-labels.ts — the two labels that say whose ball a node's turn is, moved together.
3	 *
4	 * `atomaton/in-progress` says work is in flight under the node: a run executing, or
5	 * a turn parked on agents working under it (#208). `atomaton/waiting-for-person`
6	 * says the turn came back and the machinery is waiting for a person (#223). The two
7	 * are complementary by construction, which is why one function moves both: a caller
8	 * that remembered to add one and forgot the other would leave a node wearing both
9	 * or neither, and neither state is readable.
10	 *
11	 * A closed node — an issue closed, a pull request merged or dropped — carries
12	 * NEITHER (#352). The turn is over, and a label naming who holds it names nobody:
13	 * a closed issue cannot be replied to through the machinery, so the waiting side
14	 * reads as a request nobody can act on, and the running side outlives the work it
15	 * describes. This takes back half of #223's rule — that label deliberately stayed
16	 * on a closed node as the filter of work that stopped there — because the filter
17	 * caught the person's eye as a live question on work that was over (#348, #335,
18	 * #338 on the pull-request side, #342 on the issue side); the thread tells that
19	 * story instead.
20	 *
21	 * The close is enforced here, at the one function every label writer calls, rather
22	 * than at each caller: a run that merges its own pull request and ends, a hand-off
23	 * refused because the target closed, the watch healing a run that died after its
24	 * node closed — all of them arrive here carrying a phase the node has already left.
25	 * The state is read, not assumed; the writers that run AFTER a close are exactly
26	 * the ones whose phase knowledge is stale. The readers that name `closed` directly
27	 * (the close-event strips and the runner's end-of-run strip) make the same read for
28	 * the mirror reason: the runner's strip fires on every ending, open nodes included,
29	 * and only the read can tell a node this run just closed from one whose turn is
30	 * still live — an open node gets no write, so the release's `waiting-for-person`
31	 * survives it. The removals take only what the read saw on, so a strip on a node
32	 * wearing neither label makes no write either, and the repository's unlabeled
33	 * closes stay silent.
34	 *
35	 * Best effort throughout, like every label write: the thread is the turn's record
36	 * and the labels are its cache. Every failure is a warning naming what was lost.
37	 */
38	import { gh } from "../../../adapters/github/gh.ts";
39	import { getLabel } from "../../../adapters/runner/config.ts";
40	import { readTargetState } from "../../../adapters/github/target-state.ts";
41	
42	export type TurnLabelPhase =
43	  /** A run took the turn: `in-progress` on, `waiting-for-person` off. */
44	  | "running"
45	  /** The turn came back to a person: `in-progress` off, `waiting-for-person` on. */
46	  | "with-person"
47	  /** The node is closed (#352): both come off, neither goes on. */
48	  | "closed";
49	
50	export function applyTurnLabels(phase: TurnLabelPhase, repo: string, number: string): void {
51	  const inProgress = getLabel("in_progress");
52	  const waitingForPerson = getLabel("waiting_for_person");
53	  const edit = (action: "--add-label" | "--remove-label", label: string) =>
54	    gh("issue", "edit", number, action, label, ...(repo ? ["--repo", repo] : []));
55	
56	  // Created if missing, so a renamed label or a fresh config still lands. `--repo`
57	  // travels with every call: a caller working in one checkout may be applying the
58	  // labels to another repository, and a label created in the wrong one makes the
59	  // `issue edit` fail as "label not found" (the #223 review's third point).
60	  const create = (label: string, color: string, description: string) =>
61	    gh("label", "create", label, "--force", "-c", color, "-d", description, ...(repo ? ["--repo", repo] : []));
62	
63	  // What the node is wearing, from the same read that answers whether it is still
64	  // open. A caller that could not read it removes unconditionally, the way every
65	  // caller did before #352: a failed read is not an answer, and the release still
66	  // has to take its guard down. The window between this read and the removal is
67	  // the same best-effort window every label write here has always had.
68	  const state = readTargetState(number, repo);
69	  const present = state.known ? new Set(state.labels ?? []) : undefined;
70	  const remove = (label: string) => {
71	    if (present !== undefined && !present.has(label)) return;
72	    const removed = edit("--remove-label", label);
73	    if (removed.code !== 0) console.error(`::warning::could not remove '${label}' from #${number}`);
74	  };
75	
76	  // A caller that arrived here after the node closed — a release following its own
77	  // merge, a refusal aimed at a closed target — has its phase bent to `closed`
78	  // (#352). A caller that could not read the state is not told the node is open:
79	  // it keeps the phase it brought, the pre-#352 behavior, rather than guessing.
80	  // The caller that names `closed` itself reads for the mirror reason: the runner's
81	  // end-of-run strip fires on every ending, open nodes included, and only the read
82	  // can tell a node this run just closed from one whose turn is still live.
83	  let effective = phase;
84	  if (phase === "closed") {
85	    // A node the read says is open is not the strip's business: the release that
86	    // just ran may have put `waiting-for-person` on it, and a park the ending
87	    // skipped the release for is holding `in-progress`. The read failing keeps
88	    // the unconditional strip — a failed read is not an answer, and a close-event
89	    // strip must still take its labels off.
90	    if (state.known && state.state === "open") return;
91	  } else if (!state.known) {
92	    console.error(`::warning::could not read #${number}'s state (${state.why}); applying '${phase}' labels without the closed guard`);
93	  } else if (state.state !== "open") {
94	    console.error(`#${number} is closed; the turn labels come off and neither goes on (#352)`);
95	    effective = "closed";
96	  }
97	
98	  if (effective === "closed") {
99	    remove(waitingForPerson);
100	    remove(inProgress);
101	    return;
102	  }
103	
104	  if (effective === "running") {
105	    create(inProgress, "0366d6", "Issue is being worked on by an Atomaton agent");
106	    const added = edit("--add-label", inProgress);
107	    if (added.code !== 0) console.error(`::warning::could not add '${inProgress}' to #${number}`);
108	    remove(waitingForPerson);
109	    return;
110	  }
111	
112	  create(waitingForPerson, "fbca04", "The turn is with a person on this issue or pull request");
113	  remove(inProgress);
114	  const added = edit("--add-label", waitingForPerson);
115	  if (added.code !== 0) console.error(`::warning::could not add '${waitingForPerson}' to #${number}`);
116	}

